'use strict';

function createCommitGate(apply) {
  if (typeof apply !== 'function') throw new TypeError('apply must be a function');

  let status = 'idle';
  let payload = null;
  let result;

  function stage(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new TypeError('payload must be a plain object');
    }
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new TypeError('payload must be a plain object');
    }
    for (const item of Object.values(value)) {
      const valid = item === null || typeof item === 'string' || typeof item === 'boolean' ||
        (typeof item === 'number' && Number.isFinite(item));
      if (!valid) throw new TypeError('payload contains an unsupported value');
    }
    if (status !== 'idle') return false;
    payload = { ...value };
    status = 'staged';
    return true;
  }

  function commit() {
    if (status === 'committed') return result;
    if (status !== 'staged') return false;
    try {
      result = apply({ ...payload });
      status = 'committed';
      return result;
    } catch (error) {
      status = 'failed';
      throw error;
    }
  }

  function abort() {
    if (status !== 'staged') return false;
    status = 'aborted';
    return true;
  }

  function state() {
    return { status, payload: payload === null ? null : { ...payload } };
  }

  return { stage, commit, abort, state };
}

module.exports = { createCommitGate };

