'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createCommitGate']);
const { createCommitGate } = api;

assert.throws(() => createCommitGate(null), TypeError);

let applyCalls = 0;
let gate;
const resultObject = { done: true };
const original = { count: 2, label: 'x', enabled: true, optional: null };
gate = createCommitGate(payload => {
  applyCalls += 1;
  assert.deepStrictEqual(gate.state(), {
    status: 'committing',
    payload: { count: 2, label: 'x', enabled: true, optional: null }
  });
  assert.strictEqual(gate.commit(), false);
  payload.count = 999;
  return resultObject;
});
assert.deepStrictEqual(gate.state(), { status: 'idle', payload: null });
assert.strictEqual(gate.commit(), false);
assert.strictEqual(gate.abort(), false);
assert.strictEqual(gate.stage(original), true);
original.count = 50;
original.added = 'later';
assert.strictEqual(gate.stage({ another: 1 }), false);

const stagedA = gate.state();
const stagedB = gate.state();
assert.notStrictEqual(stagedA, stagedB);
assert.notStrictEqual(stagedA.payload, stagedB.payload);
stagedA.payload.count = 77;
assert.deepStrictEqual(gate.state(), {
  status: 'staged',
  payload: { count: 2, label: 'x', enabled: true, optional: null }
});
assert.strictEqual(gate.commit(), resultObject);
assert.strictEqual(gate.commit(), resultObject);
assert.strictEqual(applyCalls, 1);
assert.deepStrictEqual(gate.state(), {
  status: 'committed',
  payload: { count: 2, label: 'x', enabled: true, optional: null }
});
assert.strictEqual(gate.abort(), false);

for (const payload of [null, [], new Date(), { x: undefined }, { x: Infinity }, { x: {} }]) {
  const candidate = createCommitGate(() => undefined);
  assert.throws(() => candidate.stage(payload), TypeError);
  assert.deepStrictEqual(candidate.state(), { status: 'idle', payload: null });
}
const empty = createCommitGate(payload => Object.keys(payload).length);
assert.strictEqual(empty.stage({}), true);
assert.strictEqual(empty.commit(), 0);

const aborted = createCommitGate(() => { throw new Error('must not run'); });
assert.strictEqual(aborted.stage({ value: 1 }), true);
assert.strictEqual(aborted.abort(), true);
assert.deepStrictEqual(aborted.state(), { status: 'aborted', payload: { value: 1 } });
assert.strictEqual(aborted.abort(), false);
assert.strictEqual(aborted.commit(), false);

const failure = new Error('apply failed');
let failureCalls = 0;
const failed = createCommitGate(() => {
  failureCalls += 1;
  throw failure;
});
assert.strictEqual(failed.stage({ value: 3 }), true);
assert.throws(() => failed.commit(), error => error === failure);
assert.deepStrictEqual(failed.state(), { status: 'failed', payload: { value: 3 } });
assert.strictEqual(failed.commit(), false);
assert.strictEqual(failureCalls, 1);

